using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;

public partial class WorldUiOperations
{
    private static Vector3 PlacementCenter(Control owner,string id)
    {var document=Session(owner).Get("document").As<Resource>();var item=document.Call("component",id).As<Resource>();return document.Call("world_transform",item).AsTransform3D().AffineInverse()*Canvas(owner).Get("target").AsVector3();}
    public bool properties(Control owner,Resource item,Node parent,Settings catalog)
    {
        if(new WorldSessionOperations().source(item)==null)return false;string id=item.Get("id").AsString();var source=Source(owner,id);if(source==null)return false;parent.AddChild(new Label {Text="WORLD"});var common=new HBoxContainer();parent.AddChild(common);foreach(string caption in new[]{"✎ Draw roads","• Edit points"})Button(owner,common,caption,()=>{var canvas=Canvas(owner);canvas.Set("environment_tool",caption=="✎ Draw roads"?"Draw road":"Road points");canvas.GrabFocus();});
        var creation=new HFlowContainer();parent.AddChild(creation);var create=new MenuButton {Text="＋ Settlement ▾"};creation.AddChild(create);var profiles=new[]{"Town","Village","City"};foreach(string profile in profiles)create.GetPopup().AddItem(profile);create.GetPopup().AddSeparator("Find suitable terrain");for(int index=0;index<profiles.Length;index++)create.GetPopup().AddItem("Auto-place "+profiles[index]+"…",100+index);
        create.GetPopup().IdPressed+=index=>{if(!Fresh(create,owner))return;if(index>=100){var job=new WorldSiteRequestJob();owner.AddChild(job);job.start(owner,id,-1,profiles[index-100]);return;}var current=Source(owner,id);if(current==null)return;var next=new WorldSettlementOperations().create(current,PlacementCenter(owner,id),profiles[index],catalog["styles"].AsGodotDictionary());owner.SetMeta("world_section",2);owner.SetMeta("world_settlement_index",next.Get("settlements").AsGodotArray().Count-1);Apply(owner,id,next,"Generate settlement");};
        var forest=new MenuButton {Text="♧ Add forest ▾",Disabled=source.Get("terrain_id").AsString().Length==0};creation.AddChild(forest);var forestProfiles=catalog["forest_profiles"].AsStringArray();foreach(string profile in forestProfiles)forest.GetPopup().AddItem(profile);forest.GetPopup().IdPressed+=index=>{if(!Fresh(forest,owner))return;var current=Source(owner,id);if(current==null)return;var next=new WorldForestOperations().create(current,PlacementCenter(owner,id),forestProfiles[index],catalog["species"].AsGodotDictionary());owner.SetMeta("world_section",4);owner.SetMeta("world_forest_index",next.Get("forests").AsGodotArray().Count-1);Apply(owner,id,next,"Generate forest");};
        var objects=new MenuButton {Text="＋ Objects ▾",Disabled=source.Get("terrain_id").AsString().Length==0};creation.AddChild(objects);foreach(string caption in new[]{"Along roads…","Across region…","In clusters…","On grid…"})objects.GetPopup().AddItem(caption);objects.GetPopup().AddSeparator("Built-in editable models");var propNames=catalog["props"].AsStringArray();for(int index=0;index<propNames.Length;index++)objects.GetPopup().AddItem(propNames[index],100+index);objects.GetPopup().IdPressed+=index=>{if(!Fresh(objects,owner))return;if(index<100){add_props(owner,id,new[]{"Roadside","Region","Clusters","Grid"}[index]);return;}var current=Source(owner,id);if(current==null)return;var next=new WorldPropLibraryOperations().add(current,propNames[index-100]);owner.SetMeta("world_section",5);owner.SetMeta("world_prop_index",next.Get("prop_rules").AsGodotArray().Count-1);Apply(owner,id,next,"Populate built-in world props");};
        var sections=new OptionButton();parent.AddChild(sections);foreach(string caption in new[]{"◎ World settings","━ Roads","⌂ Settlements","▦ Regions","♧ Forests","▧ Objects","⇄ Connections","▧ Districts and blocks"})sections.AddItem(caption);int selected=Math.Clamp(owner.GetMeta("world_section",0).AsInt32(),0,7);var panels=new VBoxContainer[8];for(int index=0;index<panels.Length;index++){panels[index]=new VBoxContainer {Visible=index==selected};parent.AddChild(panels[index]);}districts(owner,id,source,panels[7],catalog["styles"].AsGodotDictionary(),catalog["district_categories"].AsStringArray());sections.Select(selected);sections.ItemSelected+=index=>{if(!Fresh(sections,owner))return;owner.SetMeta("world_section",index);for(int page=0;page<panels.Length;page++)panels[page].Visible=page==index;if(index==3){var canvas=Canvas(owner);canvas.Set("environment_tool","World regions");canvas.Get("overlay").As<CanvasItem>().QueueRedraw();}};
        var types=catalog["road_types"].AsStringArray();WorldSettings(owner,item,source,panels[0],catalog);Roads(owner,item,source,panels[1],types);settlements(owner,id,source,panels[2]);Regions(owner,id,source,panels[3]);forests(owner,id,source,panels[4],catalog["layers"].AsStringArray());props(owner,id,source,panels[5]);connections(owner,item,source,panels[6],types);compact_choices(parent);return true;
    }
}
